"""Pack health metrics for the Voltway battery library."""
from dataclasses import dataclass


@dataclass
class PackSnapshot:
    cycles: int
    depth_of_discharge: float
    temp_max_c: float


def pack_health_index(snapshot: PackSnapshot) -> int:
    """Weighted 0-100 index shown on the fleet dashboard."""
    score = 100
    score -= snapshot.cycles // 50
    score -= int(snapshot.depth_of_discharge * 20)
    score -= int(max(0.0, snapshot.temp_max_c - 45.0) * 2)
    return max(0, min(100, score))


def packs_below_threshold(snapshots, threshold: int) -> list:
    return [s for s in snapshots if pack_health_index(s) < threshold]

